/* Сбор таблиц: отчёты «для печати» (сметы, заказы, расчёты, реестры) из файлов, папки или листов этой
   книги — в одну умную таблицу со столбцами «Файл», «Лист», «Вид». Каждую таблицу разбирает общий кусок
   ОТЧЁТ: шапка по словарю, строки-разделы (этапы), объединения, итоги со сверкой, подвал. Название этапа
   у таблиц, где этап только номером (расчёт стоимости к заказу), берётся по номеру из других листов того же
   файла. Журнал сборки — что где нашлось, чего не было, что не сошлось с итогами. */
/* ===== ОТЧЁТ — таблица из отчёта «для печати» =====
   Над таблицей — заголовки документа, под ней — итоги, подписи и текст; внутри — строки-разделы
   (этапы и подэтапы), объединённые клетки и промежуточные итоги. Здесь — только разбор значений
   листа, без вызовов приложения: ряды — двумерный массив, как его отдаёт прочитать() без
   заполнения; объединения — адреса «A5:A12» или {r1, c1, r2, c2} с нуля; формулы — такой же массив
   текстов формул или null. Общий кусок «Сбора таблиц» и «Схемы из таблицы».

   ОТЧЁТ.словарь(текст)  — строки «Имя: синоним; синоним» → [{имя, синонимы}]
   ОТЧЁТ.разобрать(ряды, объединения, формулы, о) → {найдено, причина, шапка, вид, столбцы, записи,
     разделов, итоги, сверка, пропущено}; о — {словарь, итоги (слова), раздел (куда текст строк-разделов),
     незнакомые (брать столбцы не из словаря), имяЛиста}.

   Шапка — строка (или две: «Срок» над «начало» и «окончание»), где больше всего названий из словаря;
   строка номеров столбцов под ней (1, 2, 3… или 1, 7, 8, 9) пропускается. Строка таблицы — та, где хотя бы
   три значимых клетки (ноль из формулы шаблона не в счёт) или число в «числовом» столбце; строка из
   одного-двух текстов либо с текстом на объединении во всю ширину — раздел: его текст идёт в столбец
   раздела (уровень по нумерации: «Этап 1.» и «1.» — этап, «1.1» — подэтап) и переходит на строки ниже,
   номер — в свой столбец. Итог — строка со словом «Итого», «Всего», «НДС…» или с формулой суммы; её
   числа сверяются с суммой строк. После последней строки таблицы — подвал, он не берётся. */
const ОТЧЁТ = (() => {
  /* для сравнения: строчные, ё → е, всё, кроме букв и цифр, — пробел */
  const норм = s => String(s == null ? '' : s).toLowerCase().replace(/ё/g, 'е').replace(/[^\p{L}\p{N}№]+/gu, ' ').trim();
  const пусто = v => v === null || v === undefined || (typeof v === 'string' && v.trim() === '');
  const текст = v => typeof v === 'string' && v.trim() !== '';
  const число = v => typeof v === 'number' && isFinite(v);
  const БУКВЫ = c => { let s = ''; c++; while(c > 0){ const m = (c - 1) % 26; s = String.fromCharCode(65 + m) + s; c = Math.floor((c - 1) / 26); } return s; };
  const столбецИз = б => { let n = 0; for(const ch of б.toUpperCase()) n = n * 26 + ch.charCodeAt(0) - 64; return n - 1; };
  function область(а){
    if(а && typeof а === 'object') return {r1: а.r1, c1: а.c1, r2: а.r2, c2: а.c2};
    const m = /^\$?([A-Za-z]{1,3})\$?(\d+)(?::\$?([A-Za-z]{1,3})\$?(\d+))?$/.exec(String(а || '').replace(/^.*!/, '').trim());
    if(!m) return null;
    const r1 = +m[2] - 1, c1 = столбецИз(m[1]), r2 = m[4] ? +m[4] - 1 : r1, c2 = m[3] ? столбецИз(m[3]) : c1;
    return {r1: Math.min(r1, r2), c1: Math.min(c1, c2), r2: Math.max(r1, r2), c2: Math.max(c1, c2)};
  }
  /* «Имя: синоним; синоним», по строке на столбец; «#» — примечание */
  function словарь(т){
    const out = [];
    for(const строка of String(т || '').split(/\r?\n/)){
      const s = строка.replace(/#.*$/, '').trim();
      if(!s) continue;
      const i = s.indexOf(':');
      const имя = (i < 0 ? s : s.slice(0, i)).trim();
      if(!имя) continue;
      const синонимы = [имя].concat(i < 0 ? [] : s.slice(i + 1).split(';')).map(норм).filter(Boolean);
      out.push({имя, синонимы: [...new Set(синонимы)]});
    }
    return out;
  }
  /* название столбца → имя из словаря: целиком (3), с начала (2), внутри словами (1); длиннее синоним — точнее */
  function сопоставить(заголовок, слов){
    const h = норм(заголовок);
    if(!h) return null;
    let лучш = null;
    for(const з of слов) for(const с of з.синонимы){
      let о = 0;
      if(h === с) о = 3;
      else if(h.startsWith(с + ' ')) о = 2;
      else if((' ' + h + ' ').includes(' ' + с + ' ')) о = 1;
      if(!о) continue;
      const вес = о * 1000 + с.length;
      if(!лучш || вес > лучш.вес) лучш = {имя: з.имя, оценка: о, вес};
    }
    return лучш;
  }
  /* строка номеров столбцов под шапкой: только целые, не меньше трёх, по возрастанию */
  function нумерация(ряд, c1, c2){
    const ч = [];
    for(let c = c1; c <= c2; c++){ const v = ряд && ряд[c]; if(пусто(v)) continue; if(!число(v) || v !== Math.round(v)) return false; ч.push(v); }
    return ч.length >= 3 && ч.every((x, i) => !i || x > ч[i - 1]);
  }
  const УРОВЕНЬ = /^\s*(?:этап|раздел|часть|глава|стадия)?\s*№?\s*(\d+(?:\.\d+)*)[.)]?\s+\S/i;
  function уровеньРаздела(т){ const m = УРОВЕНЬ.exec(String(т)); return m ? Math.min(2, m[1].split('.').length) : 1; }

  function разобрать(ряды, объединения, формулы, о){
    о = о || {};
    const слов = Array.isArray(о.словарь) ? о.словарь : словарь(о.словарь || '');
    const итогоСлова = (о.итоги || ['итого', 'всего', 'ндс', 'в том числе']).map(норм).filter(Boolean);
    const раздел = о.раздел || 'Этап', подраздел = 'Под' + раздел.toLowerCase();
    const R = ряды.length, C = Math.max(0, ...ряды.map(р => (р || []).length));
    const кл = (r, c) => (ряды[r] || [])[c];
    const фл = (r, c) => формулы && формулы[r] ? формулы[r][c] : null;
    /* объединения: у клетки — своё (левая верхняя), остальные клетки — «под объединением» */
    const обл = (объединения || []).map(область).filter(a => a && (a.r2 > a.r1 || a.c2 > a.c1));
    const подОбъединением = new Map();               // "r:c" → объединение (кроме левой верхней)
    const начало = new Map();                        // "r:c" левой верхней → объединение
    for(const a of обл){
      начало.set(a.r1 + ':' + a.c1, a);
      for(let r = a.r1; r <= a.r2; r++) for(let c = a.c1; c <= a.c2; c++) if(r !== a.r1 || c !== a.c1) подОбъединением.set(r + ':' + c, a);
    }
    /* ---- шапка ---- */
    const имяСтолбца = (r, c, двеСтроки) => {
      const верх = подОбъединением.get(r + ':' + c), вверху = верх ? кл(верх.r1, верх.c1) : кл(r, c);
      if(!двеСтроки) return текст(вверху) ? String(вверху).replace(/\s+/g, ' ').trim() : '';
      const сам = (верх && верх.r2 > r) || (начало.get(r + ':' + c) && начало.get(r + ':' + c).r2 > r);   // объединение и на нижнюю строку
      const низ = кл(r + 1, c);
      const в = текст(вверху) ? String(вверху).replace(/\s+/g, ' ').trim() : '', н = !сам && текст(низ) ? String(низ).replace(/\s+/g, ' ').trim() : '';
      return в && н && норм(в) !== норм(н) ? в + ' / ' + н : (в || н);
    };
    const оценитьШапку = (r, две) => {
      const имена = [];
      let c1 = Infinity, c2 = -1, текстов = 0;
      for(let c = 0; c < C; c++){ const и = имяСтолбца(r, c, две); имена.push(и); if(и){ текстов++; c1 = Math.min(c1, c); c2 = Math.max(c2, c); } }
      if(текстов < 2) return null;
      const выходы = new Set();
      for(const и of имена){ if(!и) continue; const м = сопоставить(и, слов) || (и.includes(' / ') ? сопоставить(и.split(' / ').pop(), слов) : null); if(м) выходы.add(м.имя); }
      /* шапке нужны данные под ней: хотя бы одна строка с двумя значениями в первых десяти */
      let данные = false;
      for(let k = r + (две ? 2 : 1); k < Math.min(R, r + 14) && !данные; k++){ let n = 0; for(let c = c1; c <= c2; c++) if(!пусто(кл(k, c))) n++; if(n >= 2) данные = true; }
      if(!данные) return null;
      return {строка: r, две, имена, c1, c2, оценка: выходы.size * 10 + текстов - (две ? 0.5 : 0), совпало: выходы.size};
    };
    let шапка = null;
    for(let r = 0; r < Math.min(R, 60); r++){
      for(const две of [false, true]){
        if(две){
          /* вторая строка шапки — если над ней объединение на несколько столбцов или сквозь обе строки */
          let есть = false;
          for(const a of обл) if(a.r1 === r && ((a.c2 > a.c1 && a.r2 === r) || a.r2 === r + 1)) есть = true;
          if(!есть || r + 1 >= R) continue;
        }
        const о2 = оценитьШапку(r, две);
        if(о2 && (!шапка || о2.оценка > шапка.оценка)) шапка = о2;
      }
    }
    if(!шапка || (слов.length && !шапка.совпало && шапка.имена.filter(Boolean).length < 3))
      return {найдено: false, причина: 'шапка таблицы не найдена: ни одного названия столбца из словаря', записи: [], столбцы: []};
    let тело = шапка.строка + (шапка.две ? 2 : 1);
    const нумер = нумерация(ряды[тело], шапка.c1, шапка.c2);
    if(нумер) тело++;
    const {c1, c2} = шапка;
    /* ---- столбцы ---- */
    const занято = new Map();                         // имя выхода → индекс столбца с лучшей оценкой
    const столбцы = [];
    for(let c = c1; c <= c2; c++){
      const заг = шапка.имена[c] || '';
      const м = заг ? (сопоставить(заг, слов) || (заг.includes(' / ') ? сопоставить(заг.split(' / ').pop(), слов) : null)) : null;
      const ст = {c, заголовок: заг || 'Столбец ' + БУКВЫ(c), имя: null, оценка: 0};
      if(м){
        const был = занято.get(м.имя);
        if(был === undefined || столбцы[был].вес < м.вес){
          if(был !== undefined){ столбцы[был].имя = null; столбцы[был].оценка = 0; }
          ст.имя = м.имя; ст.оценка = м.оценка; ст.вес = м.вес; занято.set(м.имя, столбцы.length);
        }
      }
      столбцы.push(ст);
    }
    /* ---- строки ---- */
    const итогоТекст = т => { const n = норм(т); return итогоСлова.some(w => n === w || n.startsWith(w + ' ')); };
    const суммаФормула = f => typeof f === 'string' && /^=?\s*(sum|сумм|subtotal|промежуточные\.?итоги|aggregate)\s*\(/i.test(f.replace(/^=/, ''));
    const ширина = c2 - c1 + 1;
    const вид = new Array(R).fill('');
    for(let r = тело; r < R; r++){
      let знач = 0, текстов = 0, итого = false, сумма = false, широкий = false;
      for(let c = c1; c <= c2; c++){
        if(подОбъединением.has(r + ':' + c)) continue;
        const v = кл(r, c);
        if(пусто(v)) continue;
        if(текст(v)){ текстов++; if(итогоТекст(v)) итого = true; }
        if(!(число(v) && v === 0)) знач++;
        if(суммаФормула(фл(r, c))) сумма = true;
        const a = начало.get(r + ':' + c);
        if(a && a.r2 === a.r1 && текст(v) && a.c2 - a.c1 + 1 >= Math.max(3, Math.ceil(ширина / 2))) широкий = true;
      }
      if(итого && текстов <= 3 || сумма && !текстов) вид[r] = 'итог';
      else if(!знач) вид[r] = 'пусто';
      else if(широкий) вид[r] = 'раздел';
      else if(знач >= 3) вид[r] = 'данные';
      else вид[r] = '?';
    }
    /* числовые столбцы — где у строк таблицы большей частью числа */
    const числовой = new Set();
    {
      const строк = [];
      for(let r = тело; r < R; r++) if(вид[r] === 'данные') строк.push(r);
      for(let c = c1; c <= c2; c++){
        let n = 0; for(const r of строк) if(!подОбъединением.has(r + ':' + c) && число(кл(r, c))) n++;
        if(строк.length && n / строк.length >= 0.6) числовой.add(c);
      }
    }
    for(let r = тело; r < R; r++){
      if(вид[r] !== '?') continue;
      let есть = false, тексты = false;
      for(let c = c1; c <= c2; c++){
        if(подОбъединением.has(r + ':' + c)) continue;
        const v = кл(r, c);
        if(числовой.has(c) && число(v) && v !== 0) есть = true;
        if(текст(v)) тексты = true;
      }
      вид[r] = есть ? 'данные' : тексты ? 'раздел' : 'пусто';
    }
    let последняя = -1;
    for(let r = тело; r < R; r++) if(вид[r] === 'данные') последняя = r;
    if(последняя < 0) return {найдено: false, причина: 'под шапкой (строка ' + (шапка.строка + 1) + ') нет строк таблицы', шапка: {строка: шапка.строка + 1}, записи: [], столбцы};
    /* ---- значения: своё, иначе — левая верхняя вертикального объединения внутри таблицы ---- */
    const значение = (r, c) => {
      const a = подОбъединением.get(r + ':' + c);
      if(!a) return кл(r, c);
      return a.r2 > a.r1 && a.c2 === a.c1 && a.r1 >= тело - 1 ? кл(a.r1, a.c1) : null;
    };
    const имяВ = c => { const ст = столбцы[c - c1]; return ст.имя || (о.незнакомые === false ? null : ст.заголовок); };
    const цельРаздела = new Set();                     // столбцы, куда разделы кладут свой текст
    for(const ст of столбцы) if(ст.имя === раздел) цельРаздела.add(ст.c);
    const записи = [], итоги = [], активно = {};
    let разделов = 0, пропущеноИтогов = 0, пустых = 0;
    let отСверки = записи.length;
    const сверка = {всего: 0, сошлось: 0, расхождения: []};
    const числаСтолбцов = new Set([...числовой].filter(c => столбцы[c - c1]));
    const сверить = r => {
      const т = (() => { for(let c = c1; c <= c2; c++) if(текст(кл(r, c))) return String(кл(r, c)).trim(); return 'итог'; })();
      if(/с ндс|ндс\s*\d|^ндс/i.test(т) && !/без ндс/i.test(т)) return;
      for(const c of числаСтолбцов){
        const v = кл(r, c);
        if(!число(v)) continue;
        const имя = имяВ(c); if(!имя) continue;
        const часть = записи.slice(отСверки).reduce((s, з) => s + (число(з.поля[имя]) ? з.поля[имя] : 0), 0);
        const все = записи.reduce((s, з) => s + (число(з.поля[имя]) ? з.поля[имя] : 0), 0);
        const итогов = итоги.filter(и => и.значения[имя] !== undefined && !и.общий).reduce((s, и) => s + и.значения[имя], 0);
        сверка.всего++;
        if(Math.abs(часть - v) < 0.01 || Math.abs(все - v) < 0.01 || (итогов && Math.abs(итогов - v) < 0.01)) сверка.сошлось++;
        else сверка.расхождения.push({строка: r + 1, текст: т, столбец: имя, вТаблице: Math.round((записи.length > отСверки ? часть : все) * 100) / 100, вИтоге: v});
      }
    };
    for(let r = тело; r < R; r++){
      const в = вид[r];
      if(в === 'итог'){
        const знач = {};
        for(let c = c1; c <= c2; c++){ const и = имяВ(c), v = кл(r, c); if(и && число(v)) знач[и] = v; }
        сверить(r);
        итоги.push({строка: r + 1, значения: знач, общий: записи.length > 0 && отСверки === записи.length});
        отСверки = записи.length; пропущеноИтогов++;
        continue;
      }
      /* за последней строкой таблицы — только итоги (через пустые строки шаблона); дальше подвал */
      if(r > последняя){ if(в === 'пусто') continue; break; }
      if(в === 'пусто'){ пустых++; continue; }
      if(в === 'раздел'){
        разделов++;
        for(let c = c1; c <= c2; c++){
          if(подОбъединением.has(r + ':' + c)) continue;
          const v = кл(r, c);
          if(пусто(v)) continue;
          const и = имяВ(c);
          if(число(v)){ if(и && и !== раздел) активно[и] = v; continue; }
          const ур = уровеньРаздела(v);
          if(ур === 1){ активно[раздел] = String(v).replace(/\s+/g, ' ').trim(); delete активно[подраздел]; }
          else активно[подраздел] = String(v).replace(/\s+/g, ' ').trim();
        }
        continue;
      }
      /* строка таблицы */
      const поля = {};
      for(let c = c1; c <= c2; c++){
        const и = имяВ(c); if(!и) continue;
        let v = значение(r, c);
        if(typeof v === 'string') v = v.replace(/\s+/g, ' ').trim();
        if(пусто(v)) continue;
        if(цельРаздела.has(c) && активно[раздел] !== undefined && норм(v) !== норм(активно[раздел])){
          if(поля[подраздел] === undefined) поля[подраздел] = v;
          continue;
        }
        поля[и] = v;
      }
      for(const [k, v] of Object.entries(активно)) if(поля[k] === undefined) поля[k] = v;
      записи.push({строка: r + 1, поля});
    }
    /* «Этап» с одними целыми — это номер этапа, если в словаре есть «Этап №» и он не занят */
    for(const ст of столбцы){
      if(!ст.имя || занято.has(ст.имя + ' №') || !слов.some(з => з.имя === ст.имя + ' №')) continue;
      const vs = записи.map(з => з.поля[ст.имя]).filter(v => !пусто(v));
      if(vs.length && vs.filter(v => число(v) && v === Math.round(v)).length / vs.length >= 0.8){
        const старое = ст.имя, новое = ст.имя + ' №';
        for(const з of записи) if(з.поля[старое] !== undefined && число(з.поля[старое])){ з.поля[новое] = з.поля[старое]; delete з.поля[старое]; }
        ст.имя = новое; занято.set(новое, столбцы.indexOf(ст));
      }
    }
    /* вид документа — самый верхний короткий заголовок над шапкой («Заказ № 17» → «Заказ») */
    let видДок = '';
    for(let r = 0; r < шапка.строка && !видДок; r++) for(let c = 0; c < C && !видДок; c++){
      const v = кл(r, c);
